    const apps=[["JT AI Agent","Research, chat history, project reasoning","/jt-ai-agent/","Workspace"],["Agent Jeff","Desktop agent for approved Windows workflows","/jt-apps/agent-jeff/","Published v0.1.0"],["JT AI Core","Provider settings and permission policy","/jt-apps/jt-ai-core/","Local prototype"],["JT Cloud","Local project records and file references","/jt-apps/jt-cloud/","Local prototype"],["JT Code","HTML/CSS/JS sandbox playground","/jt-apps/jt-code/","Local prototype"],["JT Design","Layered SVG graphics and export","/jt-apps/jt-design/","Local prototype"],["JT Motion","Local media bin, previews and shot-list export","/jt-apps/jt-motion/","Local prototype"],["JT Stream","Camera/screen scene composition and WebM recording","/jt-apps/jt-stream/","Stage 01"],["JT Studio","Audio monitor, recording and session planning","/jt-apps/jt-studio/","Local prototype"]];
    const renderCatalog=()=>{const q=document.getElementById("catalogSearch").value.toLowerCase();const found=apps.filter(x=>(x.join(" ").toLowerCase()).includes(q));document.getElementById("catalogList").innerHTML=found.map(x=>'<div class="jt-pro-item"><div><strong>'+esc(x[0])+'</strong><small>'+esc(x[1])+'</small><small>Status: '+esc(x[3])+'</small></div><a class="jt-pro-btn" href="'+esc(x[2])+'">Open ↗</a></div>').join("")||'<div class="jt-pro-empty">No matching apps.</div>';};
    document.getElementById("catalogSearch").addEventListener("input",renderCatalog);renderCatalog();
    section.addEventListener("click",async e=>{if(e.target.closest("[data-pro]")?.dataset.pro!=="refresh-releases")return;const b=e.target.closest("[data-pro]");b.disabled=true;setStatus("releaseLabStatus","Fetching public GitHub release metadata…");try{const res=await fetch("https://api.github.com/repos/Tech-guy7-sys/jt-digital-world/releases?per_page=20",{headers:{Accept:"application/vnd.github+json"},cache:"no-store",signal:AbortSignal.timeout(8000)});if(!res.ok)throw new Error("GitHub API HTTP "+res.status);const releases=(await res.json()).filter(x=>!x.draft);document.getElementById("releaseLabList").innerHTML=releases.length?releases.map(x=>'<div class="jt-pro-item"><div><strong>'+esc(x.name||x.tag_name)+'</strong><small>'+esc(x.tag_name)+' · '+(x.prerelease?"Pre-release":"Release")+' · '+esc((x.published_at||x.created_at||"").slice(0,10))+'</small><small>'+x.assets.length+' published asset(s)</small>'+(x.assets.length?'<div class="jt-pro-list">'+x.assets.map(a=>'<div class="jt-pro-item"><div><strong>'+esc(a.name)+'</strong><small>'+(Math.max(0,Number(a.size)||0)/1048576).toFixed(1)+' MB · '+(Number(a.download_count)||0)+' download(s)</small></div><a class="jt-pro-btn" href="'+esc(a.browser_download_url)+'" target="_blank" rel="noopener">Download ↗</a></div>').join('')+'</div>':'<small>No downloadable files attached.</small>')+'</div><a class="jt-pro-btn" href="'+esc(x.html_url)+'" target="_blank" rel="noopener">Release notes ↗</a></div>').join(""):'<div class="jt-pro-empty">No public releases found.</div>';setStatus("releaseLabStatus","Loaded "+releases.length+" published release(s). This repository currently has a published release for Agent Jeff only; the other JT apps do not yet have their own releases. Verify downloads before installing.");}catch(err){setStatus("releaseLabStatus","Could not load release feed: "+err.message,true);}finally{b.disabled=false;}});
