    const connectorPanel=document.createElement("div");connectorPanel.className="jt-pro-card";connectorPanel.style.marginTop="13px";connectorPanel.innerHTML='<h3>Cloud provider connectors</h3><p>Connector status is intentionally disconnected until a real OAuth flow and provider API are configured. Do not enter passwords or access tokens here.</p><div class="jt-pro-list"><div class="jt-pro-item"><div><strong>Microsoft OneDrive</strong><small>Planned: Microsoft Graph OAuth, file listing, upload/download, sync and conflict handling.</small></div><span class="jt-pro-badge">Not connected</span></div><div class="jt-pro-item"><div><strong>Apple iCloud Drive</strong><small>Planned: supported OS file-provider integration. No general-purpose iCloud Drive API is enabled in this browser prototype.</small></div><span class="jt-pro-badge">Native integration needed</span></div><div class="jt-pro-item"><div><strong>Google Drive</strong><small>Potential later connector after OAuth, scopes, and sync tests are implemented.</small></div><span class="jt-pro-badge">Roadmap</span></div></div><div class="jt-pro-row" style="margin-top:12px"><a class="jt-pro-btn" href="https://learn.microsoft.com/onedrive/developer/" target="_blank" rel="noopener">OneDrive developer docs ↗</a><a class="jt-pro-btn" href="https://www.icloud.com/iclouddrive/" target="_blank" rel="noopener">iCloud Drive ↗</a></div>';
