    const buildCodingBrief=()=>{const target=document.getElementById("codingAgentTarget").value,task=document.getElementById("codingAgentTask").value.trim();const brief='JT CODE — CODING AGENT HANDOFF\nTarget: '+target+'\n\nTask\n'+(task||'[Describe the task]')+'\n\nRepository and safety instructions\n- Inspect the repository and current working tree before changing files.\n- Propose a concise plan before implementation.\n- Preserve existing behavior and JT branding.\n- Do not overwrite unrelated changes or expose credentials.\n- Make the smallest complete implementation and add/update tests.\n- Run relevant tests and report exact commands/results.\n- Summarize changed files, risks, and remaining work.\n- Ask before destructive commands, external publishing, or production deployment.';document.getElementById("codingAgentBrief").value=brief;document.getElementById("codingAgentStatus").textContent='Brief prepared for '+target+'. Run it in that agent separately; no command was executed.';return brief;};
    handoff.addEventListener("click",async e=>{const action=e.target.closest("[data-pro]")?.dataset.pro;if(!action?.startsWith("code-handoff"))return;const brief=buildCodingBrief();if(action==="code-handoff-copy"){try{await navigator.clipboard.writeText(brief);document.getElementById("codingAgentStatus").textContent="Brief copied to clipboard.";}catch{document.getElementById("codingAgentStatus").textContent="Clipboard permission unavailable; select the brief text and copy it manually.";}}if(action==="code-handoff-download")download("jt-code-agent-handoff.txt",brief,"text/plain;charset=utf-8");});
    let active="html";const source=document.getElementById("codeSource");const tabs=document.getElementById("codeTab");const renderTab=()=>{source.value=s[active]||"";document.querySelectorAll("[data-code-file]").forEach(x=>x.classList.toggle("active",x.dataset.codeFile===active));};const run=()=>{const doc='<!doctype html><html><head><meta charset="utf-8"><style>'+s.css+'</style></head><body>'+s.html+'<script>'+s.js.replace(/<\/script/gi,"<\\/script")+'<\/script></body></html>';document.getElementById("codeFrame").srcdoc=doc;setStatus("codeProStatus","Preview refreshed in the sandbox.");};tabs.addEventListener("change",()=>{s[active]=source.value;active=tabs.value;renderTab();});source.addEventListener("input",()=>{s[active]=source.value;});source.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key==="Enter"){e.preventDefault();s[active]=source.value;run();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="s"){e.preventDefault();s[active]=source.value;setStatus("codeProStatus",save(s)?"Project draft saved locally.":"Could not save draft.",!localStorage);}});const importInput=document.getElementById("codeImportFile");importInput.addEventListener("change",async()=>{const file=importInput.files?.[0];if(!file)return;try{if(file.size>1024*1024)throw new Error("File exceeds the 1 MB import limit.");const ext=file.name.toLowerCase().split(".").pop();const kind=ext==="css"?"css":(["js","mjs"].includes(ext)?"js":(["html","htm"].includes(ext)?"html":""));if(!kind)throw new Error("Choose an HTML, CSS or JavaScript file.");s[kind]=await file.text();active=kind;tabs.value=kind;renderTab();setStatus("codeProStatus","Imported "+file.name+" into "+kind+". Save the draft to keep it in this browser.");}catch(err){setStatus("codeProStatus",err.message||"Could not import file.",true);}finally{importInput.value="";}});section.addEventListener("click",e=>{const a=e.target.closest("[data-pro]")?.dataset.pro;if(a==="code-import"){importInput.click();}if(a==="code-export-file"){s[active]=source.value;const ext=active==="html"?"html":active==="css"?"css":"js";download(active==="html"?"index.html":active==="css"?"styles.css":"app.js",s[active],active==="html"?"text/html;charset=utf-8":active==="css"?"text/css;charset=utf-8":"text/javascript;charset=utf-8");}if(a==="code-run"){s[active]=source.value;run();}if(a==="code-save"){s[active]=source.value;setStatus("codeProStatus",save(s)?"Project draft saved locally.":"Could not save draft.",!localStorage);}if(a==="code-download"){s[active]=source.value;const doc='<!doctype html><html><head><meta charset="utf-8"><style>'+s.css+'</style></head><body>'+s.html+'<script>'+s.js.replace(/<\/script/gi,"<\\/script")+'<\/script></body></html>';download("jt-code-project.html",doc,"text/html;charset=utf-8");}if(a==="code-reset"){if(confirm("Reset the three editor files to the starter project?")){s.html='<main><h1>Hello from JT Code</h1><p>Edit HTML, CSS and JavaScript, then preview.</p><button id="demoButton">Test interaction</button></main>';s.css='body{font-family:system-ui;padding:2rem;background:#f5f6ff;color:#191a2a}button{padding:.7rem 1rem;border:0;border-radius:8px;background:#7d79ff;color:white}';s.js='document.getElementById("demoButton")?.addEventListener("click",()=>alert("Sandbox is running!"));';active="html";tabs.value=active;renderTab();run();}}});renderTab();run();
